DO $dadyoom$
DECLARE r record; target_id uuid; prior text; nact integer; nused integer;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"9baee109-e1d0-4609-b470-d545bd0f7bd7","n":1,"title":"علاقة الشعر الجاهلي بالحياة","passage":"يمكن دراسة الشعر الجاهلي بوصفه شاهدًا أدبيًا على تصورات وتجارب متنوعة في بيئته، لكن صورة القبيلة في قصيدة لا تمثل جميع الناس أو حدثًا تاريخيًا ثابتًا. يتحقق الطالب من النص ونسبته قبل الاستشهاد ويقارن أغراض الشعر بالحياة الاجتماعية.","question":"ما الطريقة المسؤولة للاستدلال على حياة الجاهليين من الشعر؟","correct":"قراءة شواهد موثقة مع مراعاة السياق وحدود التعميم","wrong":["تعميم بيت واحد على الجميع","اعتبار كل صورة واقعة تاريخية","اختلاق قصيدة مناسبة"],"practice":"اختر بيتًا جاهليًا محققًا، وناقش علاقة صورة فيه بموقف اجتماعي مع حدود الاستنتاج.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"9baee109-e1d0-4609-b470-d545bd0f7bd7","n":2,"title":"أغراض الشعر الجاهلي","passage":"تعددت أغراض الشعر الجاهلي كالفخر والمدح والهجاء والرثاء والوصف والغزل، وقد يجمع النص الواحد أكثر من غرض. يدل الغرض من المخاطب والمعجم العاطفي والموقف في القصيدة، لا من اسم الشاعر وحده.","question":"أي غرض شعري يدل غالبًا على الاعتزاز بالذات أو الجماعة؟","correct":"الفخر","wrong":["الرثاء دائمًا","الوصف الحيادي","الاعتذار وحده"],"practice":"حلل قصيدتين موثقتين بغرضين مختلفين وبيّن الألفاظ الدالة عليهما.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"9baee109-e1d0-4609-b470-d545bd0f7bd7","n":3,"title":"خصائص الشعر الجاهلي","passage":"من ملامح الشعر الجاهلي الشائعة البناء العمودي والوزن والقافية والتصوير المرتبط بعالم التجربة، لكنها لا تظهر بالتطابق في كل نص أو غرض. قد تبدأ قصائد تقليدية بأطلال وقد تبدأ أخرى بموضوع مغاير؛ ويتطلب التعميم مقارنة نصوص محققة.","question":"ما القرينة الأوضح على البناء العمودي في قصيدة؟","correct":"انتظام الأبيات على وزن وبنية عروضية","wrong":["ذكر الصحراء وحده","شهرة الشاعر فقط","عنوان قديم"],"practice":"قارن مطلعين موثقين للشعر الجاهلي في الصورة وبنية البيت.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"9baee109-e1d0-4609-b470-d545bd0f7bd7","n":4,"title":"المعلقات في العصر الجاهلي","passage":"يطلق اسم المعلقات على قصائد طويلة مشهورة في التراث العربي مع اختلاف بعض المصادر في عددها وتفاصيل تسميتها. لا يجوز عرض قصة تعليقها في الكعبة بوصفها حقيقة تاريخية مجمعًا عليها دون توثيق ونقاش للمصادر.","question":"ما الموقف العلمي المناسب من رواية سبب تسمية المعلقات؟","correct":"عرض اختلاف المصادر دون جزم غير مثبت","wrong":["اعتبار كل رواية حقيقة","اختراع سند","تجاهل اختلاف الباحثين"],"practice":"صمم بطاقة تعريف بمعلقة واحدة مع الشاعر والمصدر والبناء الفني دون أبيات غير محققة.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"adb0c6b0-a11a-42bc-b67d-812c51722a49","n":2,"title":"التجديد في الشعر العباسي","passage":"شهدت بعض التجارب الشعرية في العصر العباسي تجديدًا في الموضوع والصورة واللغة والبناء مع استمرار الأوزان القديمة في كثير من الشعر؛ لا يعني التجديد الانقطاع الكامل عن التراث. تُدرس ملامحه بمقارنة نصين صحيحَي النسبة.","question":"ما الدليل الملائم على تجديد صورة شعرية؟","correct":"مقارنة الصورة ومقامها مع نموذج سابق موثق","wrong":["تاريخ ولادة الشاعر وحده","عدد أبيات القصيدة","البلد دون نص"],"practice":"قارن صورتين شعريتين من عصرين في الموضوع والأسلوب مع مصدر لكل نص.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"adb0c6b0-a11a-42bc-b67d-812c51722a49","n":3,"title":"الموضوعات الشعرية","passage":"تنوعت موضوعات الشعر العباسي بين المدح والهجاء والوصف والتأمل والزهد والغزل ومشاغل الحياة، لكن لا تنسب الأغراض كلها بالقدر نفسه لكل شاعر. يُربط الغرض بالمعجم والصورة والمخاطب في قصيدة معينة.","question":"ما الذي يحدد الموضوع الشعري عند التحليل؟","correct":"شواهد من ألفاظ القصيدة وصورها في سياقها","wrong":["اسم العصر وحده","عدد الكلمات","الانطباع المسبق"],"practice":"أعد خريطة لأربعة أغراض في قصائد عباسية موثقة مع شاهد لكل غرض.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"edeb5418-2ecd-48bc-a99e-679abb94a222","n":1,"title":"أثر الإسلام في الشعر والنثر","passage":"اتصلت تحولات الشعر والنثر في صدر الإسلام بتغيرات دينية واجتماعية ولغوية، ويجب تحليل أثر المفاهيم الجديدة في نصوص محققة مع التمييز بين الشعر والخطابة والحديث والقرآن. لا يجوز اختلاق عبارة دينية أو قصيدة للتدليل.","question":"ما الذي يلزم لنسبة أثر ديني إلى نص أدبي؟","correct":"توثيق النص ومقارنة لغته وسياقه","wrong":["توليد آية تقريبية","الاعتماد على العنوان","اختلاق خطبة"],"practice":"اقرأ نصًا أدبيًا صحيحًا من المرحلة وبيّن أثر قيمة أو معنى فيه بشاهد.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"edeb5418-2ecd-48bc-a99e-679abb94a222","n":2,"title":"تحليل نماذج شعرية في مدح الرسول ﷺ","passage":"يتطلب تحليل مدح الرسول ﷺ اختيار أبيات صحيحة النسبة من مصدر معتبر، وعدم خلطها بالنص القرآني أو الحديث النبوي. يقرأ الطالب ألفاظ التعظيم والصور والإيقاع وفق سياق القصيدة دون إضافة أقوال أو أخبار تاريخية لم تثبت.","question":"ما الضابط قبل نقل بيت في المديح النبوي؟","correct":"تحقيق النص ونسبته إلى الشاعر","wrong":["إنشاء بيت ثم نسبته","نسخ نص مجهول","استخلاص الرواية من العنوان"],"practice":"حلل شاهدًا صحيحًا من قصيدة مدح نبوي مع ذكر المصدر والغرض الفني.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"edeb5418-2ecd-48bc-a99e-679abb94a222","n":3,"title":"ظاهرة الغزل في الشعر الأموي","passage":"اتسع الشعر الأموي لتجارب غزل متنوعة تختلف في صوت المتكلم وطريقة تصوير المحبوب والبيئة الاجتماعية، ولا تختزل في صورة واحدة. تُفرق القراءة بين تجربة فنية وشهادة تاريخية عبر الألفاظ والبناء والمخاطب.","question":"ما العنصر الذي يفيد في تصنيف تجربة الغزل شعريًا؟","correct":"طبيعة الخطاب والصور والسياق","wrong":["اسم الشاعر وحده","عدد الصفحات","قافية موحدة فقط"],"practice":"قارن مثالين موثقين من غزل العصر الأموي في نبرة العاطفة والمخاطب.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"edeb5418-2ecd-48bc-a99e-679abb94a222","n":4,"title":"شعر النقائض","passage":"تُبنى النقائض على الرد الشعري بين شاعرين باستخدام صور من المعارضة والجدل، وقد تتشابه الأوزان والقوافي في نصين متقابلين. يحتاج الطالب نصين موثقين لإدراك موضع الرد ولا يصح اعتماد نادرة متداولة بلا مصدر.","question":"ما السمة التي تساعد على فهم النقائض؟","correct":"وجود جواب شعري يعارض قولًا في نص آخر","wrong":["غياب المخاطب دائمًا","كل قصيدة مدح نقائض","مجرّد تقارب أسماء الشعراء"],"practice":"اقرأ مثالين متقابلين موثقين وحدد دعوى وردًا مع مراعاة أدب النقد.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"edeb5418-2ecd-48bc-a99e-679abb94a222","n":5,"title":"النثر في عصر صدر الإسلام والعصر الأموي","passage":"تتنوع الأجناس النثرية في هذين العصرين مثل الخطابة والرسائل ضمن سياقات اجتماعية وسياسية ودينية، ويلزم توثيق الصيغ المنقولة من كتب الأدب والتاريخ. يختلف الإيقاع النثري وبناء الحجج عن الوزن العروضي للقصيدة.","question":"أي جنس أدبي يعتمد خطابًا شفهيًا لجمهور مع حجج؟","correct":"الخطابة","wrong":["القصيدة العمودية بالضرورة","الموشح حتمًا","التقطيع العروضي"],"practice":"حلل فقرة نثرية موثقة من العصر وتبين غرضها وترتيب حججها.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"787eeed4-9456-4ac9-b928-bd4b6e40b16f","n":1,"title":"المفعول المطلق","passage":"المفعول المطلق مصدر منصوب من لفظ الفعل أو معناه لتوكيد الحدث أو بيان نوعه أو عدده؛ ففي «قرأ الطالبُ قراءةً متأنيةً» المصدر «قراءةً» يبين نوع القراءة. يميز التحليل بين المصدر ووظيفته وبين المفعول به.","question":"ما إعراب «قراءةً» في المثال؟","correct":"مفعول مطلق منصوب","wrong":["فاعل مرفوع","اسم مجرور","مفعول به"],"practice":"اكتب ثلاثة أمثلة للمفعول المطلق بحسب وظائفه مع الإعراب.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"787eeed4-9456-4ac9-b928-bd4b6e40b16f","n":2,"title":"الممنوع من الصرف","passage":"الاسم الممنوع من الصرف قد يجر بالفتحة بدل الكسرة إذا لم يكن مضافًا ولا محلى بأل في مواضع معروفة؛ مثل «مررتُ بأحمدَ». تختلف أسباب المنع ولا يُنزع التنوين من كل علم دون مراعاة الصيغة والقاعدة.","question":"ما علامة الجر في «مررت بأحمدَ» في المثال؟","correct":"الفتحة نيابة عن الكسرة","wrong":["الضمة","السكون","حذف النون"],"practice":"صنف ستة أسماء ممنوعة من الصرف وأعربها مع الإضافة أو أل.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"787eeed4-9456-4ac9-b928-bd4b6e40b16f","n":3,"title":"الاستثناء","passage":"يتغير إعراب المستثنى بأداة «إلا» حسب تمام الجملة ونفيها؛ ففي التام المثبت «حضر الطلاب إلا طالبًا» يُنصب المستثنى، أما المنفي والمفرغ فيحتاجان تحليلًا مختلفًا. تحديد النوع يسبق ضبط الكلمة.","question":"ما إعراب «طالبًا» في الاستثناء التام المثبت؟","correct":"مستثنى منصوب","wrong":["فاعل مرفوع","خبر إن","اسم مجرور"],"practice":"حلل ثلاث جمل استثناء: تام مثبت وتام منفي وناقص منفي.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"787eeed4-9456-4ac9-b928-bd4b6e40b16f","n":4,"title":"الجمل التي لها محل من الإعراب","passage":"قد تقع جملة فعلية خبرًا مثل «الطالبُ يقرأُ كتابه» حيث جملة «يقرأ كتابه» في محل رفع خبر المبتدأ، وقد تقع الجمل نعتًا أو حالًا أو مفعولًا في سياقات أخرى. لا نحكم على محل جملة قبل تحديد ما تتعلق به.","question":"ما محل الجملة «يقرأ كتابه» في المثال؟","correct":"في محل رفع خبر","wrong":["في محل جر دائمًا","لا محل لها","بدل اسم مفرد"],"practice":"حدد وظيفة أربع جمل فعلية واقعة في تراكيب مختلفة مع الإعراب.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"787eeed4-9456-4ac9-b928-bd4b6e40b16f","n":5,"title":"التعجب","passage":"تُصاغ بعض أساليب التعجب القياسية على «ما أفعله!» و«أفعل به!» عندما تستوفي الأفعال شروط الصياغة، مثل «ما أجملَ التعاونَ!». لا تصح كل صيغة من أي فعل دون النظر إلى شروطه الصرفية والدلالية.","question":"ما نوع «ما أجمل التعاون»؟","correct":"تعجب قياسي","wrong":["نداء","استثناء","نهي"],"practice":"اكتب أربعة تراكيب للتعجب مع الضبط وتوضيح الصيغة.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"787eeed4-9456-4ac9-b928-bd4b6e40b16f","n":6,"title":"الإضافة","passage":"تربط الإضافة بين مضاف ومضاف إليه مجرور مثل «كتابُ الطالبِ»، ويُحذف التنوين من المضاف في الإضافة المعنوية. تختلف الدلالات المحتملة بين التخصيص والتعريف وعلاقة الملك أو النوع بحسب السياق.","question":"ما إعراب «الطالبِ» في «كتاب الطالب»؟","correct":"مضاف إليه مجرور","wrong":["فاعل","حال","مفعول مطلق"],"practice":"اكتب خمسة تراكيب إضافية ونوع العلاقة بين المضاف والمضاف إليه.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"787eeed4-9456-4ac9-b928-bd4b6e40b16f","n":7,"title":"موسيقا الشعر","passage":"تتشكل موسيقا الشعر من الوزن والقافية والإيقاع الداخلي كالتكرار والتوازي، ولا يكفي تقارب نهايات الكلمات للحكم بأن الأبيات على البحر نفسه. يُستعمل التقطيع العروضي على المنطوق مع نص صحيح مضبوط.","question":"ما الوسيلة المناسبة للتحقق من الوزن الشعري؟","correct":"التقطيع العروضي","wrong":["عد أسطر القصيدة فقط","موضوع القصيدة","اسم الشاعر وحده"],"practice":"قارن بيتين موثقين في الإيقاع الخارجي والداخلي دون اختلاق شواهد.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"fe115461-47f3-4c1b-9567-ada4ce8f0ab6","n":1,"title":"اللزوميات","passage":"ترتبط «اللزوميات» بنتاج أبي العلاء المعري الشعري وتُدرس خصائص الالتزام في القافية ضمن سياق نصوص صحيحة النسبة، مع تجنب اختلاق أبيات أو نسبة موقف فلسفي إليه دون شاهد. التحليل يجمع الإيقاع والمعنى ومقام الخطاب.","question":"ما الذي ينبغي تحليله في قصيدة من اللزوميات؟","correct":"نظام القافية وصلة الشكل بالمعنى في النص","wrong":["العنوان وحده","قول مختلق","قصيدة شاعر آخر"],"practice":"اختر مقطعًا موثقًا من اللزوميات وحلل قافيته وفكرته مع مصدره.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"fe115461-47f3-4c1b-9567-ada4ce8f0ab6","n":2,"title":"الروميات","passage":"ترتبط «الروميات» بأبي فراس الحمداني في تراث الشعر العربي، وتتطلب دراستها نصوصًا صحيحة النسبة وفهم دور صوت المتكلم والظرف في بناء العاطفة، دون اختلاق وقائع الأسر أو أبيات جديدة على لسانه.","question":"ما الضابط المناسب لتحليل تجربة المتكلم في الروميات؟","correct":"الرجوع إلى أبيات موثقة وسياقها","wrong":["الاعتماد على قصة متداولة فقط","تأليف بيت","افتراض تفاصيل تاريخية"],"practice":"حلل مقطعًا مرخصًا من الروميات وناقش صورتين عاطفيتين.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"fe115461-47f3-4c1b-9567-ada4ce8f0ab6","n":3,"title":"الحكمة في شعر المتنبي","passage":"تظهر معانٍ حكمية في شعر المتنبي بوصفها تأملات وعِبرًا نابعة من سياقات القصائد، لكن لا يصح توليد أقوال جديدة ونسبتها إليه. نفحص المعنى العام والصورة والحدود التي تمنع تعميم الخبر الشعري كحقيقة مطلقة.","question":"ما دليل وجود معنى حكمي في بيت للمتنبي؟","correct":"شاهد صحيح يفيد معنى تأمليًا مع تفسير","wrong":["اسمه وحده","حكمة من إنشاء الطالب","خبر مجهول"],"practice":"اختر بيتًا صحيح النسبة، وفسر دلالته والموقف الذي جاء فيه.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"},{"cid":"270026e3-1832-49b3-a580-89708396bb6d","unit":"fe115461-47f3-4c1b-9567-ada4ce8f0ab6","n":4,"title":"الكتابة النثرية الأدبية","passage":"تستخدم الكتابة النثرية الأدبية الوصف والسرد والإيقاع الداخلي والصورة لصياغة تجربة دون التقيد بوزن البيت الشعري. مثال مستقل «فتحت المكتبة بابها، فدخل الضوء وتبعته أسئلة الصغار» يجمع صورة ومشهدًا، ولا ينسب إلى كاتب قديم.","question":"ما العنصر الفني الظاهر في المثال المستقل؟","correct":"تصوير دخول الضوء مع بداية مشهد سردي","wrong":["تقطيع على بحر واحد","خبر قانوني","صيغة مصدر فقط"],"practice":"اكتب فقرة نثر أدبي من إنشائك وحدد صورتين وكيف تخدمان الفكرة.","old":"DADYOOM_JO_OFFICIAL_2026_2027_V1"}]'::jsonb)
 AS x(cid uuid,unit uuid,n integer,title text,passage text,question text,correct text,wrong text[],practice text,old text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,prior
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id
  JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='JO' AND c.id=r.cid AND g.grade_number=12
    AND u.semester=1 AND u.id=r.unit AND l.sort_order=r.n
    AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO nused FROM public.student_lesson_progress WHERE lesson_id=target_id;
  IF nused<>0 THEN RAISE EXCEPTION 'JO_G12_HAS_PROGRESS_%',r.title; END IF;
  SELECT count(*) INTO nused FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF nused<>0 THEN RAISE EXCEPTION 'JO_G12_HAS_ATTEMPTS_%',r.title; END IF;
  IF char_length(coalesce(prior,''))>=350 THEN RAISE EXCEPTION 'JO_G12_ALREADY_ENRICHED_%',r.title; END IF;

  SELECT count(*) INTO nact FROM public.lesson_activities
   WHERE lesson_id=target_id AND content->>'origin'=r.old;
  IF nact<>3 THEN RAISE EXCEPTION 'JO_G12_EXPECTED_THREE_ACTIVITIES_%',r.title; END IF;
  SELECT count(*) INTO nact FROM public.lesson_activities
   WHERE lesson_id=target_id AND content->>'origin'=r.old
     AND ((activity_order IN (1,2) AND activity_type='multiple_choice')
       OR (activity_order=3 AND activity_type IN ('reading','writing')));
  IF nact<>3 THEN RAISE EXCEPTION 'JO_G12_ACTIVITY_SHAPE_MISMATCH_%',r.title; END IF;

  UPDATE public.lessons SET
   content='ضاديوم — إثراء تعليمي أصلي للصف الثاني عشر بالأردن؛ لا يمثل نص الكتاب المدرسي ولا إثبات مطابقة كل صفحة أو فصل. عناوين الدروس مستوردة وتحتاج تحققًا من الفهرس الرسمي.'
   ||E'\n\n'||'الدرس: '||r.title
   ||E'\n\n'||'هدف: أن يفسر المتعلم فكرة الدرس بدليل أو مثال صحيح، ويطبق مهارة تحليلية مع تعليل إجابة اختيار متعدد.'
   ||E'\n\n'||'شرح أصلي: '||r.passage
   ||E'\n\n'||'سؤال للفهم: '||r.question
   ||E'\n\n'||'تطبيق أصلي: '||r.practice
   ||E'\n\n'||'تدرّج التعلم: يبدأ المتعلم بتحديد المفهوم، ثم يفسر الدليل، ثم يختبر قراءة بديلة أو يستخدم مثالًا من إنشائه. يتولى المعلم مراجعة مهام الكتابة عند وجودها.'
   ||E'\n\n'||'توثيق: تُقرأ النصوص التاريخية والدينية والشعرية من نسخ أصلية موثقة، ولا تُنسب إليها أمثلة ضاديوم المستقلة.'
   ||E'\n\n'||'المحتوى السابق المحفوظ: '||coalesce(prior,''),
   updated_at=now()
   WHERE id=target_id;

  UPDATE public.lesson_activities SET
   prompt=r.question,
   content=content||jsonb_build_object('origin','DADYOOM_JO_G12_ORIGINAL_22_20261009',
     'previousOrigin',r.old,'text',r.question,'sourceVerification','pending',
     'notOfficialBook',true,
     'options',jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])),
   answer=jsonb_build_object('correct',r.correct)
   WHERE lesson_id=target_id AND activity_order=1 AND activity_type='multiple_choice'
     AND content->>'origin'=r.old;

  UPDATE public.lesson_activities SET
   prompt='أي نشاط تدريبي يمثل تطبيقًا ملائمًا لدرس «'||r.title||'»؟',
   content=content||jsonb_build_object('origin','DADYOOM_JO_G12_ORIGINAL_22_20261009',
     'previousOrigin',r.old,'sourceVerification','pending','notOfficialBook',true,
     'text','أي نشاط تدريبي يمثل تطبيقًا ملائمًا لدرس «'||r.title||'»؟',
     'options',jsonb_build_array('أنسخ الجواب دون الرجوع إلى القاعدة أو المصدر',
     'أختلق شاهدًا غير موجود ليدعم رأيي',
     r.practice,
     'أقفز إلى النتيجة قبل دراسة النص أو المثال')),
   answer=jsonb_build_object('correct',r.practice)
   WHERE lesson_id=target_id AND activity_order=2 AND activity_type='multiple_choice'
     AND content->>'origin'=r.old;

  UPDATE public.lesson_activities SET
   prompt='اقرأ الشرح التدريبي وفسر شاهدًا واحدًا صحيحًا مع احترام مصدر النص.',
   content=content||jsonb_build_object('origin','DADYOOM_JO_G12_ORIGINAL_22_20261009',
     'previousOrigin',r.old,'sourceVerification','pending','notOfficialBook',true,
     'text',r.passage)
   WHERE lesson_id=target_id AND activity_order=3 AND activity_type='reading'
     AND content->>'origin'=r.old;

  UPDATE public.lesson_activities SET
   prompt=r.practice,
   content=content||jsonb_build_object('origin','DADYOOM_JO_G12_ORIGINAL_22_20261009',
     'previousOrigin',r.old,'sourceVerification','pending','notOfficialBook',true,
     'text',r.practice,'humanReviewRequired',true)
   WHERE lesson_id=target_id AND activity_order=3 AND activity_type='writing'
     AND content->>'origin'=r.old;

  SELECT count(*) INTO nact FROM public.lesson_activities WHERE lesson_id=target_id
    AND content->>'origin'='DADYOOM_JO_G12_ORIGINAL_22_20261009';
  IF nact<>3 THEN RAISE EXCEPTION 'JO_G12_UPDATE_MISSING_ACTIVITY_%',r.title; END IF;
 END LOOP;
END $dadyoom$;